def transform(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,value in enumerate(row) if value==8}
    pieces=[]
    height,width=len(grid),len(grid[0])
    for r in range(height-1):
        for c in range(width-1):
            square={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if square <= cells:
                pieces.append((square,1))
            # Color is determined by which corner of a 2x2 L is absent.
            for missing,label in [((0,0),2),((1,0),3),((0,1),4)]:
                shape=square-{(r+missing[0],c+missing[1])}
                if shape <= cells:
                    pieces.append((shape,label))
    by_cell={cell:[piece for piece in pieces if cell in piece[0]] for cell in cells}
    solutions=[]
    def search(remaining,chosen):
        if not remaining:
            solutions.append(chosen)
            return
        cell=min(remaining,key=lambda x:sum(piece[0] <= remaining for piece in by_cell[x]))
        for piece in by_cell[cell]:
            if piece[0] <= remaining:
                search(remaining-piece[0],chosen+[piece])
                if len(solutions)>1:
                    return
    search(cells,[])
    if not solutions:
        raise ValueError('No tiling found')
    out=[[0 for _ in row] for row in grid]
    for shape,label in solutions[0]:
        for r,c in shape:
            out[r][c]=label
    return out

